VALUES (277154, 'tt2544766', NULL, 'Admiral', 'Michiel de Ruyter', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/li4FlbrBWWNk9VnyATNXVYIU7hl.jpg', 'https://image.tmdb.org/t/p/original/1mOD7BGsHrj3SWvq8L2GyjqvbKV.jpg', 'When the young republic of The Netherlands is attacked by England, France and Germany and faces its own civil war no less, only one man, Michael de Ruyter, can lead the county''s strongest weapon, the Dutch fleet.', NULL, NULL, 3.6841, 6.4, 0, 10.52, '2026-10-17 15:53:06', '2026-10-17 15:53:06')
