VALUES (11162, 'tt0379889', NULL, 'The Merchant of Venice', 'The Merchant of Venice', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/bvpPg5oTD1qT7hjY3BOsoniYdHG.jpg', 'https://image.tmdb.org/t/p/original/2fX8oILb0dGsGH4E6biP2WWlf91.jpg', 'Venice, 1596. Bassanio begs his friend Antonio, a prosperous merchant, to lend him a large sum of money so that he can woo Portia, a very wealthy heiress; but Antonio has invested his fortune abroad, so they turn to Shylock, a Jewish moneylender, and ask him for a loan.', NULL, NULL, 6.5009, 6.793, 0, 10.51, '2026-10-17 15:53:06', '2026-10-17 15:53:06')
