VALUES (NULL, NULL, 8965, 'Darkest Dungeon', 'Darkest Dungeon', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaw2.jpg', NULL, 'Darkest Dungeon is a challenging gothic roguelike turn-based RPG about the psychological stresses of adventuring. Recruit, train, and lead a team of flawed heroes against unimaginable horrors, stress, disease, and the ever-encroaching dark. Can you keep your heroes together when all hope is lost?', 'https://www.igdb.com/games/darkest-dungeon', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "iOS", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 10.51, '2026-10-17 15:53:06', '2026-10-17 15:53:06')
