VALUES (7131, 'tt0338526', NULL, 'Van Helsing', 'Van Helsing', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/gsFun8nATm52aGHeT8ueAel98nE.jpg', 'https://image.tmdb.org/t/p/original/d72ROyJqXQtw2OupW0l15eicRAF.jpg', 'Famed monster slayer Gabriel Van Helsing is dispatched to Transylvania to assist the last of the Valerious bloodline in defeating Count Dracula. Anna Valerious reveals that Dracula has formed an unholy alliance with Dr. Frankenstein''s monster and is hell-bent on exacting a centuries-old curse on her family.', NULL, NULL, 12.9164, 6.425, 0, 66.7374193548387, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
