VALUES (152601, 'tt1798709', NULL, 'Her', 'Her', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg', 'https://image.tmdb.org/t/p/original/sPPsR9f4K0movWVQ99u4uMqFzEL.jpg', 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.', NULL, NULL, 11.2099, 7.836, 0, 4.28662162162162161e+01, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
