VALUES (68, 'tt0088846', NULL, 'Brazil', 'Brazil', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/aewan59WcFThBimkTVVoNf2o5Vb.jpg', 'https://image.tmdb.org/t/p/original/9IYyCLf5NNAQFK9pNtqzEU9HWzM.jpg', 'Low-level bureaucrat Sam Lowry escapes the monotony of his day-to-day life through a recurring daydream of himself as a virtuous hero saving a beautiful damsel. Investigating a case that led to the wrongful arrest and eventual death of an innocent man instead of wanted terrorist Harry Tuttle, he meets the woman from his daydream, and in trying to help her gets caught in a web of mistaken identities, mindless bureaucracy and lies.', NULL, NULL, 6.0939, 7.7, 0, 1.06353861386138618e+02, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
