VALUES (57230, 'tt0062453', NULL, 'Viy', 'Вий', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/rgkp4X9C1NNobH8bq55zcMTQFCl.jpg', 'https://image.tmdb.org/t/p/original/8NdbgS3Ndc7Q8cZIuHquhID9C6j.jpg', 'A seminary student on monastery holiday kills an old witch in a remote village. The hag then transforms into a beautiful young woman whose dying wish is for him to watch over her wake for three nights. With terrors occurring and his faith waning, he reads prayers on the overnight watch and tries to survive the supernatural encounters.', NULL, NULL, 2.5133, 6.9, 0, 24.218, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
