VALUES (11305, 'tt0097940', NULL, 'Mystery Train', 'Mystery Train', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/f11xq7dBGhz9UDc3dabldAGeXVH.jpg', 'https://image.tmdb.org/t/p/original/t0GxYLiPkTtFBuzoPLmLU3HSKEN.jpg', 'In Memphis, Tennessee, over the course of a single night, the Arcade Hotel, run by an eccentric night clerk and a clueless bellboy, is visited by a young Japanese couple traveling in search of the roots of rock; an Italian woman in mourning who stumbles upon a fleeing charlatan girl; and a comical trio of accidental thieves looking for a place to hide.', NULL, NULL, 2.9681, 7.317, 0, 12.71375, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
