VALUES (1064213, 'tt28607951', NULL, 'Anora', 'Anora', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', 'https://image.tmdb.org/t/p/original/qvyOfwTC3qdbzkqdXWSSEMHtjBZ.jpg', 'A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.', NULL, NULL, 19.9382, 7.077, 0, 3.64390909090909076e+01, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
