VALUES (16052, 'tt0120094', NULL, 'Selena', 'Selena', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/j8xX3yBAFOayfSaImgLZPnAcdWz.jpg', 'https://image.tmdb.org/t/p/original/kcBlY5FasH8ti150aYExULw53ui.jpg', 'In this biographical drama, Selena Quintanilla is born into a musical Mexican-American family in Texas. Her father, Abraham, realizes that his young daughter is talented and begins performing with her at small venues. She finds success and falls for her guitarist, Chris Perez, who draws the ire of her father. Seeking mainstream stardom, Selena begins recording an English-language album which, tragically, she would never complete.', NULL, NULL, 3.7206, 7.715, 0, 6.2625, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
