VALUES (975335, 'tt36456563', NULL, 'Magellan', 'Magalhães', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/pmFeUueU7BWLVnHrYI1FD7VnxtH.jpg', 'https://image.tmdb.org/t/p/original/8nv5MUtEBMX4DDkrFkDhkppRxuD.jpg', 'At the dawn of the modern era, Portuguese explorer Ferdinand Magellan leads an expedition under the Spanish crown in search of the first westward route to the Spice Islands. He embarks on a perilous journey across the uncharted Pacific, where his fleet faces starvation, mutiny, and the psychological toll of endless seas. Upon reaching the shores of Cebu, Magellan is pulled into a fatal conflict with the natives by his drive to spread Catholicism, culminating in his tragic doom.', NULL, NULL, 5.0656, 6.3, 0, 13.224, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
