VALUES (359940, 'tt5027774', NULL, 'Three Billboards Outside Ebbing, Missouri', 'Three Billboards Outside Ebbing, Missouri', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/fQzCvF2R4P9YkPQK7gO9LNLcnlD.jpg', 'https://image.tmdb.org/t/p/original/oQHF0Y4gCw6VdPmapjsbZoxY2ht.jpg', 'After seven months have passed without a culprit in her daughter''s murder case, Mildred Hayes makes a bold move, painting three signs leading into her town with a controversial message directed at Bill Willoughby, the town''s revered chief of police. When his second-in-command Officer Jason Dixon, an immature mother''s boy with a penchant for violence, gets involved, the battle between Mildred and Ebbing''s law enforcement is only exacerbated.', NULL, NULL, 8.3006, 8.053, 0, 2.97016666666666679e+01, '2026-07-15 12:01:52', '2026-10-17 15:53:06')
