VALUES (588228, 'tt9777666', NULL, 'The Tomorrow War', 'The Tomorrow War', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', 'https://image.tmdb.org/t/p/original/yizL4cEKsVvl17Wc1mGEIrQtM2F.jpg', 'The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.', NULL, NULL, 17.0202, 7.528, 0, 1.18966666666666665e+01, '2026-07-20 01:02:04', '2026-10-17 15:53:06')
