VALUES (1084736, 'tt26446278', NULL, 'The Count of Monte Cristo', 'Le Comte de Monte-Cristo', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/sAT1P3FGhtJ68anUyJScnMu8t1l.jpg', 'https://image.tmdb.org/t/p/original/bxT8jFcWNuWK5LmVo1oGhAm4dnZ.jpg', 'Edmond Dantès becomes the target of a sinister plot and is arrested on his wedding day for a crime he did not commit. After 14 years in the island prison of Château d’If, he manages a daring escape. Now rich beyond his dreams, he assumes the identity of the Count of Monte-Cristo and exacts his revenge on the three men who betrayed him.', NULL, NULL, 12.0727, 7.899, 0, 1.16214285714285718e+01, '2026-07-29 20:51:09', '2026-10-17 15:53:06')
