VALUES (2280, 'tt0094737', NULL, 'Big', 'Big', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/eWhCDJiwxvx3YXkAFRiHjimnF0j.jpg', 'https://image.tmdb.org/t/p/original/bi9ihIMB9DoXs7odkS5oKkHoK2o.jpg', 'When a young boy makes a wish at a carnival machine to be big—he wakes up the following morning to find that it has been granted and his body has grown older overnight. But he is still the same 13-year-old boy inside. Now he must learn how to cope with the unfamiliar world of grown-ups including getting a job and having his first romantic encounter with a woman.', NULL, NULL, 6.891, 7.19, 0, 1.2951818181818183e+01, '2026-07-30 18:28:39', '2026-10-17 15:53:06')
