VALUES (27378, 'tt0074626', NULL, 'Heart of Glass', 'Herz aus Glas', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/yaYs87zLoXTK1pPKSMfJQRnwxgL.jpg', 'https://image.tmdb.org/t/p/original/i3oAgy8mKIoVW9ZWhzYAYV2HxGh.jpg', 'A small Bavarian village is renowned for its "Ruby Glass" glass blowing works. When the foreman of the works dies suddenly without revealing the secret of the Ruby Glass, the town slides into a deep depression, and the owner of the glassworks becomes obssessed with the lost secret.', NULL, NULL, 1.9638, 6.5, 0, 9.84333333333333193e+00, '2026-08-08 02:23:49', '2026-10-17 15:53:06')
