VALUES (57212, 'tt1568911', NULL, 'War Horse', 'War Horse', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/3aRHhvvngFPJFy5uAjo7GVr3PhL.jpg', 'https://image.tmdb.org/t/p/original/tcx15vswrQJCGET5lGxESQ4J5LG.jpg', 'On the brink of the First World War, Albert''s beloved horse Joey is sold to the Cavalry by his father. Against the backdrop of the Great War, Joey begins an odyssey full of danger, joy, and sorrow, and he transforms everyone he meets along the way. Meanwhile, Albert, unable to forget his equine friend, searches the battlefields of France to find Joey and bring him home.', NULL, NULL, 7.8396, 7.305, 0, 4.01, '2026-08-11 22:09:33', '2026-10-17 15:53:06')
