VALUES (9620, 'tt0338337', NULL, 'Paycheck', 'Paycheck', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/h0BWaPnWYXwbCXF69DxS0YWcVy2.jpg', 'https://image.tmdb.org/t/p/original/rdlXnumaarKFHQ4rB8YBWINEeuE.jpg', 'Michael Jennings is a genius who''s hired – and paid handsomely – by high-tech firms to work on highly sensitive projects, after which his short-term memory is erased so he''s incapable of breaching security. But at the end of a three-year job, he''s told he isn''t getting a paycheck and instead receives a mysterious envelope. In it are clues he must piece together to find out why he wasn''t paid – and why he''s now in hot water.', NULL, NULL, 5.7671, 6.22, 0, 5.52, '2026-08-22 01:37:44', '2026-10-17 15:53:06')
